insert into tap_results select ok((select bool_and(relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r'),'All public tables have RLS');
insert into tap_results select ok(not has_function_privilege('anon','public.agri_command(text,jsonb)','execute'),'Anonymous callers cannot execute transaction API');
insert into tap_results select ok(not has_table_privilege('authenticated','public.sales','insert'),'Authenticated users cannot bypass transaction functions');
insert into tap_results select lives_ok($$select public.agri_command('open_shift',jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(101),'deviceId',pg_temp.i(501),'openingCash',10000))$$,'Cashier opens an authorized shift');
insert into tap_results select lives_ok($$select public.agri_command('record_sale',pg_temp.payload(701))$$,'Fractional sack sale commits atomically');
insert into tap_results select is((select count(*)::integer from public.sales),1,'One sale recorded');
insert into tap_results select is((select quantity::text from public.branch_inventory where branch_id=pg_temp.i(101)),'475.000000','Half a sack deducts exactly 25 kg');
insert into tap_results select is((select sum(amount)::bigint from public.payments),75000::bigint,'Cash payment matches sale total');
insert into tap_results select is(public.agri_command('record_sale',pg_temp.payload(701))->>'status','duplicate','Lost acknowledgment retry returns duplicate');
insert into tap_results select is((select count(*)::integer from public.inventory_movements where kind='sale'),1,'Retry creates no duplicate journal entry');
insert into tap_results select is(public.agri_command('record_sale',pg_temp.payload(701)||'{"cashReceived":110000}'::jsonb)->>'status','review','Changed payload under the same ID is rejected for review');
insert into tap_results select is((select cash_received from public.sales where id=pg_temp.i(701)),100000::bigint,'Original cash amount is immutable');
insert into tap_results select lives_ok($$select public.agri_command('record_sale',pg_temp.payload(702))$$,'Separate identical purchase receives its own transaction');
insert into tap_results select is((select count(*)::integer from public.sales),2,'Identical purchases are not collapsed');
insert into tap_results select throws_ok($$select public.agri_command('snapshot',jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(102),'transactionIds','[]'::jsonb))$$,'42501','You do not have access to this branch','Cashier cannot query another branch through RPC');
insert into tap_results select is((select count(*)::integer from public.branch_inventory where branch_id=pg_temp.i(102)),0,'RLS hides other branch stock');
insert into tap_results select is((select count(*)::integer from public.products where organization_id=pg_temp.i(2)),0,'RLS hides other businesses');
insert into tap_results select throws_ok($$update public.branch_inventory set quantity=9999$$,'42501',null,'Direct stock edits are denied');
insert into tap_results select throws_ok($$select public.agri_command('set_price',jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(101),'unitId',pg_temp.i(401),'price',1,'cost',1))$$,'42501','Only the owner can change prices','Cashier cannot alter prices');
insert into tap_results select throws_ok($$select public.agri_command('start_blind_count',jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(101),'countId',pg_temp.i(901),'productId',pg_temp.i(301),'reason','TEST count'))$$,'42501','Stock count access denied','Cashier cannot adjust stock through counts');
insert into tap_results select throws_ok($$select public.agri_command('record_sale',pg_temp.payload(799)||jsonb_build_object('occurredAt','2020-01-01T00:00:00Z'))$$,'P0001','Sale falls outside the authorized shift window','Expired offline authorization is rejected on server');
insert into tap_results select lives_ok($$select public.agri_command('set_price',jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(101),'unitId',pg_temp.i(401),'price',160000,'cost',125000))$$,'Owner creates a new price version');
insert into tap_results select is((select count(*)::integer from public.unit_prices where unit_id=pg_temp.i(401)),2,'Previous price remains available for offline validation');
insert into tap_results select ok((public.agri_command('record_sale',pg_temp.payload(703))->'flags')?'price_changed','Real offline sale retains cached price and flags its changed version');
insert into tap_results select lives_ok($$select public.agri_command('dispatch_transfer',jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(101),'transferId',pg_temp.i(801),'productId',pg_temp.i(301),'batchId',null,'quantity','50','destinationBranchId',pg_temp.i(102)))$$,'Owner dispatches transfer');
insert into tap_results select is((select quantity::text from public.branch_inventory where branch_id=pg_temp.i(102)),'200.000000','Dispatch does not prematurely increase destination stock');
insert into tap_results select lives_ok($$select public.agri_command('receive_transfer',jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(102),'transferId',pg_temp.i(801),'receiptId',pg_temp.i(802),'quantity','50','heldQuantity','0','reason','TEST delivery checked'))$$,'Destination branch confirms transfer receipt');
insert into tap_results select lives_ok($$select public.agri_command('receive_transfer',jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(102),'transferId',pg_temp.i(801),'receiptId',pg_temp.i(802),'quantity','50','heldQuantity','0','reason','TEST delivery checked'))$$,'Repeated transfer receipt is idempotent');
insert into tap_results select is((select quantity::text from public.branch_inventory where branch_id=pg_temp.i(102)),'250.000000','Destination stock increases once');
insert into tap_results select is((select count(*)::integer from public.sales),0,'Stock staff cannot read cash sale records');
insert into tap_results select throws_ok($$select public.agri_command('record_sale',pg_temp.payload(704))$$,'42501','Sales access denied','Stock staff cannot perform checkout');
insert into tap_results select throws_ok($$select public.agri_command('start_blind_count',jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(101),'countId',pg_temp.i(901),'productId',pg_temp.i(301),'reason','TEST count'))$$,'P0001','Close and synchronize every shift before counting','Physical counts require a closed branch');
insert into tap_results select lives_ok($$select public.agri_command('close_shift',jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(101),'shiftId',(select id from public.cashier_shifts where closed_at is null),'countedCash',235000))$$,'Cashier reconciles and closes shift');
insert into tap_results select is((select expected_cash from public.cashier_shifts where cashier_id=pg_temp.i(12)),235000::bigint,'Expected drawer cash includes opening float and all sales');
insert into tap_results select lives_ok($$select public.agri_command('start_blind_count',jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(101),'countId',pg_temp.i(901))||jsonb_build_object('productId',pg_temp.i(301),'reason','Physical count test'));select public.agri_command('record_blind_count',jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(101),'countId',pg_temp.i(901))||jsonb_build_object('stage','first','quantity','370','notes','Physical first count','observationId',pg_temp.i(903)))$$,'Stock staff submits discrepancy without changing stock');
insert into tap_results select throws_ok($$select public.agri_command('approve_count',jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(101),'countId',pg_temp.i(901)))$$,'42501','Only the owner can approve an adjustment','Stock staff cannot approve their own discrepancy');
insert into tap_results select lives_ok($$select public.agri_command('record_blind_count',jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(101),'countId',pg_temp.i(901))||jsonb_build_object('stage','recount','quantity','370','notes','Physical independent count','observationId',pg_temp.i(904)))$$,'Independent stock staff seals matching recount');
insert into tap_results select is((select quantity::text from public.branch_inventory where branch_id=pg_temp.i(101)),'375.000000','Pending count has not changed inventory');
insert into tap_results select lives_ok($$select public.agri_command('approve_count',jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(101),'countId',pg_temp.i(901),'reason','TEST independently approved'))$$,'Owner approval posts a linked adjustment');
insert into tap_results select lives_ok($$select public.agri_command('approve_count',jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(101),'countId',pg_temp.i(901),'reason','TEST independently approved'))$$,'Repeated count approval is idempotent');
insert into tap_results select is((select quantity::text from public.branch_inventory where branch_id=pg_temp.i(101)),'370.000000','Approved discrepancy reconciles stock once');
insert into tap_results select is((public.agri_command('dashboard',jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(101)))->>'grossSales')::bigint,225000::bigint,'Owner report totals are computed server-side');
insert into tap_results select throws_ok($$select public.agri_command('snapshot',jsonb_build_object('organizationId',pg_temp.i(2),'branchId',pg_temp.i(201)))$$,'42501','You do not have access to this branch','Owner cannot cross business boundaries');
insert into tap_results select throws_ok($$update public.sales set total=1 where id=pg_temp.i(701)$$,'P0001','History is immutable; create a linked reversal','Even privileged writes cannot rewrite sale history');
